#!/usr/bin/env python3
import sys
import struct
import os
from pwn import *

def analyze_cell(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    print(f"Analyzing file of size {len(data)} bytes")

    # Check for patterns or signatures
    # The first bytes look like they might contain some header information
    # Let's look at the first few words
    for i in range(0, min(128, len(data)), 4):
        val = struct.unpack(">I", data[i:i+4])[0]  # Big-endian
        print(f"Offset {i:04x}: {val:08x}")

    # Look for any string data within the file
    strings = []
    current_string = ""
    for i, b in enumerate(data):
        if 32 <= b <= 126:  # Printable ASCII
            current_string += chr(b)
        else:
            if len(current_string) > 4:  # Only store strings longer than 4 chars
                strings.append((i - len(current_string), current_string))
            current_string = ""

    if current_string and len(current_string) > 4:
        strings.append((len(data) - len(current_string), current_string))

    print("\nFound strings:")
    for offset, string in strings:
        print(f"Offset {offset:08x}: {string}")

    # Let's try to find the flag format csaw_ctf{...}
    for offset, string in strings:
        if "csaw_ctf{" in string:
            print(f"\nPossible flag found at offset {offset:08x}: {string}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <file>")
        sys.exit(1)

    analyze_cell(sys.argv[1])

